create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 2 and 30), avatar_url text, invite_code text unique not null default upper(substr(encode(gen_random_bytes(6),'hex'),1,8)), created_at timestamptz not null default now());
create table if not exists public.friendships (user_id uuid references public.profiles(id) on delete cascade, friend_id uuid references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,friend_id), check(user_id<>friend_id));
alter table public.profiles enable row level security;alter table public.friendships enable row level security;
create policy "profiles read authenticated" on public.profiles for select to authenticated using(true);create policy "profile insert own" on public.profiles for insert to authenticated with check(auth.uid()=id);create policy "profile update own" on public.profiles for update to authenticated using(auth.uid()=id);
create policy "friendships read own" on public.friendships for select to authenticated using(auth.uid()=user_id);create policy "friendships insert own" on public.friendships for insert to authenticated with check(auth.uid()=user_id);
create or replace function public.add_friend_by_code(code_input text) returns text language plpgsql security definer set search_path=public as $$declare target uuid;begin select id into target from profiles where invite_code=upper(trim(code_input));if target is null then return 'CÓDIGO NÃO ENCONTRADO';end if;if target=auth.uid() then return 'CÓDIGO PERTENCE A VOCÊ';end if;insert into friendships(user_id,friend_id) values(auth.uid(),target),(target,auth.uid()) on conflict do nothing;return 'CONEXÃO ESTABELECIDA';end$$;
create or replace function public.get_my_friends() returns table(id uuid,display_name text,avatar_url text,invite_code text) language sql security definer set search_path=public as $$select p.id,p.display_name,p.avatar_url,p.invite_code from friendships f join profiles p on p.id=f.friend_id where f.user_id=auth.uid() order by p.display_name$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',true,3145728,array['image/png','image/jpeg','image/webp']) on conflict(id) do update set public=true,file_size_limit=3145728,allowed_mime_types=array['image/png','image/jpeg','image/webp'];
create policy "avatar public read" on storage.objects for select using(bucket_id='avatars');create policy "avatar own insert" on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);create policy "avatar own update" on storage.objects for update to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
